class Solution:
    def solve(self, nums, target):
        # 两遍哈希表：先建索引，再查找
        seen = {}
        for i, num in enumerate(nums):
            seen[num] = i
        for i, num in enumerate(nums):
            complement = target - num
            if complement in seen and seen[complement] != i:
                return [i, seen[complement]]
        return []

