class Solution:
    def solve(self, nums):
        # 分治法：最大子数组要么全在左半/右半，要么跨越中点 O(n log n)
        return self._max_sub(nums, 0, len(nums) - 1)

    def _max_sub(self, nums, l, r):
        if l == r:
            return nums[l]
        m = (l + r) // 2
        left_max = self._max_sub(nums, l, m)
        right_max = self._max_sub(nums, m + 1, r)
        # 跨越中点的最大和
        cross = 0
        cur = 0
        for i in range(m, l - 1, -1):
            cur += nums[i]
            cross = max(cross, cur)
        cur = 0
        for i in range(m + 1, r + 1):
            cur += nums[i]
            cross = max(cross, cur)
        return max(left_max, right_max, cross)

